// If dynamic services exist in template_services, merge or use them
$render_services = array();
if (!empty($tpl_services)) {
    foreach ($tpl_services as $idx => $ts) {
        $def_idx = $idx % count($default_services_data);
        $def = $default_services_data[$def_idx];

        $img_src = !empty($ts->thumbnail) ? (strpos($ts->thumbnail, 'http') === 0 ? $ts->thumbnail : base_url(ltrim($ts->thumbnail, '/'))) : $def['image'];
        $price_str = !empty($ts->price) ? ('$' . number_format((float)$ts->price, 2)) : $def['price'];
        $dur_str = !empty($ts->duration) ? (is_numeric($ts->duration) ? ($ts->duration . ' mins') : $ts->duration) : $def['duration'];
        $category = !empty($ts->tagline) ? $ts->tagline : $def['category'];

        $render_services[] = array(
            'id' => $ts->id,
            'title' => $ts->title,
            'slug' => !empty($ts->slug) ? $ts->slug : $def['slug'],
            'category' => $category,
            'image' => $img_src,
            'price' => $price_str,
            'duration' => $dur_str,
            'desc' => !empty($ts->short_desc) ? $ts->short_desc : $def['desc'],
            'icon_svg' => !empty($ts->icon) && strpos($ts->icon, '<svg') !== false ? $ts->icon : $def['icon_svg']
        );
    }
} else {
    $render_services = $default_services_data;
}
